commands.sources-check.ps1:
$ErrorActionPreference='Stop'
Set-Location O:/repos.hobby/ntvdm64
try {
 $tokens=$null;$errors=$null
 $ast=[Management.Automation.Language.Parser]::ParseFile((Resolve-Path tools/build/New-T310OriginalSoftpcNinja.ps1),[ref]$tokens,[ref]$errors)
 if($errors.Count){throw 'Generator parse errors'}
 $fn=$ast.Find({param($n) $n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Get-OriginalSources'},$true)
 if(!$fn){throw 'Original parser missing'}
 . ([scriptblock]::Create($fn.Extent.Text))
 $before=@(Get-OriginalSources build/t483-s5-p117/sources-before)
 $after=@(Get-OriginalSources build/t483-s5-p117/sources-final)
 if(Compare-Object $before $after -SyncWindow 0){throw 'Selected sources changed'}
 if($after -contains 'nt_aorc.c'){throw 'Excluded source selected'}
 [ordered]@{count=$after.Count;equal=$true;selected=$after;provider='tools/build/New-T310OriginalSoftpcNinja.ps1:Get-OriginalSources';scope='Same parser shared by x86 and x64;T313 reads CCPU manifest only'}|ConvertTo-Json -Depth 5|Set-Content build/t483-s5-p117/sources-check.json
 $node='C:/Program Files/WindowsApps/OpenAI.CodexPrimaryRuntime.v26-1112-611-0_26.1112.611.0_x64__3k8sg7r9htsxt/dependencies/node/bin/node.exe'
 & $node tools/audit/Verify-VdmTibStorage.mjs build/t483-s5-p117/restored/ntvdm.exe.map build/.ninja/msvc-x86-release/worker/obj/adapter-monitor/mvdm_vdm_tib.obj
 if($LASTEXITCODE){throw 'Restored storage guard failed'}
 0|Set-Content build/t483-s5-p117/sources-check.exit
} catch {$_|Out-String|Write-Output;1|Set-Content build/t483-s5-p117/sources-check.exit;exit 1}
